def solve(facts):
    alphabet = facts['alphabet']
    length = facts['length']
    modulus = facts['modulus']
    residue = facts['residue']
    sum_min = facts['sum_min']
    sum_max = facts['sum_max']
    target_digit = facts['target_digit']
    target_count = facts['target_count']
    # State: previous digit, residue, digit sum, target-digit count.
    dp = {}
    for d in alphabet:
        key = (d, d % modulus, d, int(d == target_digit))
        dp[key] = (1, d)
    for _ in range(1, length):
        nxt = {}
        for (prev, rem, total, cnt), (ways, digit_total) in dp.items():
            for d in alphabet:
                if d == prev:
                    continue
                new_total = total + d
                new_cnt = cnt + int(d == target_digit)
                if new_total > sum_max or new_cnt > target_count:
                    continue
                key = (d, (rem * 10 + d) % modulus, new_total, new_cnt)
                old_ways, old_total = nxt.get(key, (0, 0))
                nxt[key] = (old_ways + ways, old_total + digit_total + ways * d)
        dp = nxt
    count = 0
    digit_sum_total = 0
    for (prev, rem, total, cnt), (ways, digit_total) in dp.items():
        if rem == residue and sum_min <= total <= sum_max and cnt == target_count:
            count += ways
            digit_sum_total += digit_total
    return {'count': count, 'digit_sum_total': digit_sum_total}

