    states = [((), 0, 0, 0)]
    for _ in range(length):
        nxt = []
        for digits, rem, total, cnt in states:
            for d in alphabet:
                if digits and d == digits[-1]:
                    continue
                new_total = total + d
                new_cnt = cnt + int(d == target_digit)
                if new_total <= sum_max and new_cnt <= target_count:
